    }

    private static String membershipNumber(Owner owner) {
        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
            return null;
        }
        return owner.getCustomerCode() + "-M" + FiscalYear.twoDigit(owner.getRegistrationDate());
    }
}

